import XCTest
@testable import ChromaticCore

/// Outputs of the IPOL reference implementation (with its four code fixes applied, see README) on two small
/// inputs, pinning the method's branch order: the slice clipping, sign tests and extrema ties.
final class ReferenceFixtureTests: XCTestCase {
    private func check(width: Int, height: Int, input: [Float], expected: [Float], radius: Int, file: StaticString = #filePath, line: UInt = #line) throws {
        var rgba = [Float](); rgba.reserveCapacity(width * height * 4)
        for i in stride(from: 0, to: input.count, by: 3) { rgba += [input[i], input[i + 1], input[i + 2], 1] }
        let image = try FloatImage(width: width, height: height, rgba: rgba)
        var p = Parameters(); p.horizontalRadius = radius; p.verticalRadius = radius
        let cpu = try CPUProcessor.process(image, parameters: p)
        var outputs = [("CPU", cpu)]
        if let gpu = try? MetalProcessor() { outputs.append(("Metal", try gpu.process(image, parameters: p))) }
        for (name, out) in outputs {
            var worst: Float = 0
            for (i, value) in expected.enumerated() { worst = max(worst, abs(out.rgba[i / 3 * 4 + i % 3] - value)) }
            XCTAssertLessThan(worst, 2e-5, "\(name) departs from the reference", file: file, line: line)
        }
    }
